import { NextRequest, NextResponse } from "next/server";
import { getCurrentUser } from "@/lib/auth/session";
import { getFreemius, FreemiusError, isFreemiusSandbox } from "@/lib/billing/freemius";

const PORTAL_ENDPOINT = "/api/billing/freemius/portal";

// Two jobs, same URL, matching Freemius's own "Customer Portal" design:
//
// GET  — returns a trimmed-down view of the logged-in user's subscription
//        (renewal date, amount, and a signed `cancelRenewalUrl`/invoice URLs
//        generated by the SDK) for our own Settings & Billing UI to render.
// POST — the actual action dispatcher. The `cancelRenewalUrl` (and similar
//        signed URLs) returned by GET point back at this same endpoint; the
//        SDK's PortalRequestProcessor verifies the signature and performs the
//        requested action (e.g. cancel renewal) against the Freemius API.
export async function GET() {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  let freemius;
  try {
    freemius = getFreemius();
  } catch (err) {
    if (err instanceof FreemiusError) return NextResponse.json({ error: err.message }, { status: err.status });
    throw err;
  }

  const portalData = await freemius.customerPortal.retrieveDataByEmail({
    email: user.email,
    endpoint: PORTAL_ENDPOINT,
    sandbox: isFreemiusSandbox(),
  });

  if (!portalData || !portalData.subscriptions.primary) {
    return NextResponse.json({ subscription: null });
  }

  const sub = portalData.subscriptions.primary;
  return NextResponse.json({
    subscription: {
      planTitle: sub.planTitle,
      isActive: sub.isActive,
      renewalAmount: sub.renewalAmount,
      currency: sub.currency,
      renewalDate: sub.renewalDate,
      billingCycle: sub.billingCycle,
      cancelledAt: sub.cancelledAt ?? null,
      cancelRenewalUrl: sub.cancelRenewalUrl,
    },
    billingUpdateUrl: portalData.billing?.updateUrl ?? null,
    payments: (portalData.payments ?? []).slice(0, 10).map((p) => ({
      planTitle: p.planTitle,
      amountGross: p.gross,
      invoiceUrl: p.invoiceUrl,
      createdAt: p.createdAt,
    })),
  });
}

export async function POST(request: NextRequest) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  let freemius;
  try {
    freemius = getFreemius();
  } catch (err) {
    if (err instanceof FreemiusError) return NextResponse.json({ error: err.message }, { status: err.status });
    throw err;
  }

  const processor = freemius.customerPortal.request.createProcessor({
    portalEndpoint: PORTAL_ENDPOINT,
    isSandbox: isFreemiusSandbox(),
    // The portal's signed action URLs already identify which Freemius user
    // they apply to; we only need to hand back an email so the SDK can
    // cross-check it matches the currently logged-in PrintReady user before
    // performing the action.
    getUser: async () => ({ email: user.email }),
  });

  return processor(request);
}
